def transform(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    up = 0
    down = 0

    for r in range(rows):
        for c in range(1, cols - 1):
            if grid[r][c - 1] == grid[r][c] == grid[r][c + 1] == 2:
                if r > 0 and grid[r - 1][c] == 2:
                    up += 1
                if r + 1 < rows and grid[r + 1][c] == 2:
                    down += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]
    for count, color, offset in ((up, 3, 0), (down, 1, 3)):
        for r, c in slots[:count]:
            out[r][c + offset] = color
    return out
